        .map_err(|e| CozoError::Other(format!("delete session: {e}"))?);
        Ok(())
    }

    /// Return a shared handle to the underlying DbInstance for advanced queries.
    pub fn db(&self) -> Arc<DbInstance> {
        self.db.clone()
    }
}


