cd /home/jeremy/git/operation-dbus-proto/crates/op-plugins/src && python3 << 'EOF'
import re

with open('state_plugins/mod.rs', 'r') as f:
    content = f.read()

# Extract all pub use lines
uses = re.findall(r'pub use ([^;]+);', content)

# Parse each use line into module path and items
exports = []
for use_line in uses:
    use_line = use_line.strip()
    if '::' in use_line:
        parts = use_line.rsplit('::', 1)
        if len(parts) == 2:
            module, items = parts
            items = items.strip()
            if items.startswith('{'):
                # Multiple items: {A, B}
                items_list = [i.strip() for i in items[1:-1].split(',')]
                for item in items_list:
                    if item:
                        exports.append((module.strip(), item))
            else:
                exports.append((module.strip(), items))

# Generate the explicit pub use lines
groups = {}
for module, item in exports:
    groups.setdefault(module, []).append(item)

lines = []
for module, items in sorted(groups.items()):
    if len(items) == 1:
        lines.append(f'    pub use super::state_plugins::{module}::{items[0]};')
    else:
        items_str = ', '.join(sorted(items))
        lines.append(f'    pub use super::state_plugins::{module}::{{{items_str}}};')

result = '\n'.join(lines)
print(result)
EOF

