//! op-web: Unified Web Server for op-dbus-v2
//!
//! This crate consolidates ALL HTTP services into a single server:
//! - REST API for tools, agents, chat, status
//! - WebSocket for real-time chat
//! - MCP protocol endpoint for Claude Desktop
//! - SSE for streaming events
//! - Static file serving for web UI
//!
//! ## Architecture
//!
//! ```text
//! ┌─────────────────────────────────────────────────────────────────┐
//! │                      op-web Server (:8080)                       │
//! ├─────────────────────────────────────────────────────────────────┤
//! │  /api/health     - Health check                                 │
//! │  /api/status     - System status                                │
//! │  /api/tools      - Tool registry                                │
//! │  /api/agents     - Agent management                             │
//! │  /api/chat       - Chat API                                     │
//! │  /api/events     - SSE event stream                             │
//! │  /mcp            - MCP JSON-RPC endpoint                        │
//! │  /ws             - WebSocket chat                               │
//! │  /               - Static files (WASM frontend)                 │
//! └─────────────────────────────────────────────────────────────────┘
//! ```

pub mod chat_store;
pub mod email;
pub mod embedded_ui;
pub mod groups_admin;
pub mod handlers;
pub mod mcp;
pub mod mcp_agents;
pub mod mcp_compact;
pub mod mcp_discovery;
pub mod middleware;
pub mod orchestrator;
pub mod privacy_container;
pub mod privacy_network;
pub mod privacy_openflow;
pub mod privacy_routes;
pub mod projection_client;
pub mod routes;
pub mod sse;
pub mod state;
pub mod state_manager_client;
pub mod users;
pub mod websocket;
pub mod wireguard;
pub mod zeroclaw_routes;

pub use embedded_ui::{serve_embedded_ui, ui_available, UiAssets};
pub use orchestrator::UnifiedOrchestrator;
pub use state::AppState;

/// Server configuration
#[derive(Debug, Clone)]
pub struct ServerConfig {
    pub host: String,
    pub port: u16,
    pub static_dir: Option<String>,
    pub enable_cors: bool,
    pub enable_compression: bool,
}

impl Default for ServerConfig {
    fn default() -> Self {
        Self {
            host: "0.0.0.0".to_string(),
            port: 8080,
            static_dir: Some("static".to_string()),
            enable_cors: true,
            enable_compression: true,
        }
    }
}

//! Error types for op-gateway

#[derive(Debug, thiserror::Error)]
pub enum GatewayError {
    #[error("authentication failed: {0}")]
    AuthFailed(String),
    #[error("session not found: {0}")]
    SessionNotFound(String),
    #[error("crypto error: {0}")]
    Crypto(String),
    #[error("storage error: {0}")]
    Storage(String),
    #[error("database error: {0}")]
    Database(#[from] sqlx::Error),
    #[error("io error: {0}")]
    Io(#[from] std::io::Error),
    #[error("internal error: {0}")]
    Internal(String),
}

pub type Result<T> = std::result::Result<T, GatewayError>;

impl GatewayError {
    pub fn internal(msg: impl Into<String>) -> Self {
        Self::Internal(msg.into())
    }

    pub fn auth_failed(msg: impl Into<String>) -> Self {
        Self::AuthFailed(msg.into())
    }

    pub fn crypto(msg: impl Into<String>) -> Self {
        Self::Crypto(msg.into())
    }

    pub fn storage(msg: impl Into<String>) -> Self {
        Self::Storage(msg.into())
    }
}

