    let files = self.dbus.list_unit_files().await?;
    let mut all = Vec::new();
    for file in files {
        if let Some(name) = file.get("name").and_then(|v| v.as_str()) {
            all.push(name.to_string());
        }
    }
    Ok(all)
}

