pub fn read_gemini_cli_token() -> anyhow::Result<(String, i64)> {
    let path = gemini_creds_path().context("cannot locate ~/.gemini/oauth_creds.json")?;
    let mut text = std::fs::read_to_string(&path)
        .with_context(|| format!("cannot read {}", path.display()))?;
    let mut bytes = text.into_bytes();
    bytes.extend_from_slice(&[0; simd_json::SIMDJSON_PADDING]);
    let creds: OwnedValue = simd_json::to_owned_value(&mut bytes)
        .with_context(|| format!("cannot parse {}", path.display()))?;

    let token = creds
        .get("access_token")
        .and_then(|v| v.as_str())
        .context("missing access_token in gemini oauth_creds")?
        .to_string();
    let expiry = creds
        .get("expiry_date")
        .and_then(|v| v.as_f64())
        .map(|v| v as i64)
        .unwrap_or(0);

    Ok((token, expiry))
}

